import * as T from 'three';
import {OrbitControls} from '/simulations/vendor/OrbitControls.js';
import {sandboxWheel} from '/simulations/vendor/sandbox-camera.mjs';
import {unit,cardArmy,hexBoard,TYPES,figureCount} from './greek-battle-units.mjs';
export function createUnitPreview(host){const renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.toneMapping=T.ACESFilmicToneMapping;host.append(renderer.domElement);const scene=new T.Scene();scene.background=new T.Color('#e8e2cc');scene.add(new T.HemisphereLight('#fff4d9','#89947a',2.2));const sun=new T.DirectionalLight('#fff0da',3);sun.position.set(-3,7,5);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);Object.assign(sun.shadow.camera,{left:-6,right:6,top:6,bottom:-6,near:.1,far:20});sun.shadow.normalBias=.015;scene.add(sun);const ground=new T.Mesh(new T.PlaneGeometry(100,100),new T.MeshStandardMaterial({color:'#e8e2cc',roughness:1}));ground.rotation.x=-Math.PI/2;ground.position.y=-.24;ground.receiveShadow=true;scene.add(ground);const camera=new T.PerspectiveCamera(33,1,.01,100),orbit=new OrbitControls(camera,renderer.domElement);orbit.mouseButtons={LEFT:T.MOUSE.ROTATE,MIDDLE:T.MOUSE.ROTATE,RIGHT:T.MOUSE.PAN};orbit.touches={ONE:T.TOUCH.ROTATE,TWO:T.TOUCH.DOLLY_PAN};orbit.minDistance=2;orbit.maxDistance=30;orbit.maxPolarAngle=Math.PI*.47;renderer.domElement.addEventListener('wheel',e=>{e.preventDefault();e.stopImmediatePropagation();sandboxWheel(T,camera,orbit,e);},{capture:true,passive:false});let content;
const shotLabels=['close-up','squad'].map(kind=>{const label=document.createElement('div');label.dataset.shot=kind;label.style.cssText='position:absolute;z-index:2;pointer-events:none;transform:translate(-50%,-100%);padding:5px 9px;border-radius:8px;background:rgba(255,252,240,.92);color:#4c4330;font:600 12px var(--app-font,Manrope,sans-serif);text-align:center;white-space:nowrap;box-shadow:0 1px 4px #0001';host.append(label);return label;});
const lineupLink=document.createElement('a');lineupLink.href='/greek-character-lineup.html';lineupLink.textContent='Character styles →';lineupLink.style.cssText='position:absolute;right:12px;bottom:12px;z-index:3;background:#fffcf0;color:#4c4330;padding:8px 12px;border-radius:9px;font:600 12px var(--app-font,Manrope,sans-serif)';host.append(lineupLink);
const labelPoint=new T.Vector3();
function positionLabels(){if(!content)return;[content.children[1],content.children[2]].forEach((model,i)=>{const box=new T.Box3().setFromObject(model);box.getCenter(labelPoint);labelPoint.y=box.max.y+.12;labelPoint.project(camera);const x=Math.max(shotLabels[i].offsetWidth/2+8,Math.min(host.clientWidth-shotLabels[i].offsetWidth/2-8,(labelPoint.x+1)*host.clientWidth/2));const y=Math.max(62,Math.min(host.clientHeight-8,(1-labelPoint.y)*host.clientHeight/2));shotLabels[i].style.left=x+'px';shotLabels[i].style.top=y+'px';});}

function resize(){const w=host.clientWidth,h=host.clientHeight;if(!w||!h)return;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix();}new ResizeObserver(()=>{resize();fitPose();}).observe(host);
function fitPose(){const phone=camera.aspect<.85;if(content){const [base,model,squad]=content.children;base.position.set(phone?0:-1.45,0,phone?-1.25:0);model.position.set(phone?0:-1.45,.04,phone?-1.25:0);squad.position.set(phone?0:1.25,0,phone?1.35:0);}orbit.target.set(0,.6,0);const distance=Math.max(phone?7.4:9,(phone?2.8:5.6)/(2*Math.tan(33*Math.PI/360)*camera.aspect))*1.08;camera.position.copy(orbit.target).add(new T.Vector3(phone?0:3.7,3.7,7.8).normalize().multiplyScalar(distance));orbit.update();}function fit(){resize();fitPose();}
function show(v=4,c=0){shotLabels[0].textContent=`${TYPES[v]} · Close-up`;shotLabels[1].textContent=`${TYPES[v]} · Squad of ${figureCount(v)}`;if(content)scene.remove(content);content=new T.Group();const base=hexBoard('clay',.9);base.position.x=-1.45;content.add(base);const model=unit(v,c,'crown','#bd6489');model.scale.setScalar(v>=9?1.45:2.1);model.position.set(-1.45,.04,0);model.rotation.y=Math.PI+.25;content.add(model);const squad=cardArmy({id:`${c}-${v}`,v,c},'olive','crown','#bd6489');squad.position.set(1.25,0,0);squad.rotation.y=Math.PI;content.add(squad);scene.add(content);fit();}
function tick(){if(host.offsetParent&&!document.hidden){renderer.render(scene,camera);positionLabels();}requestAnimationFrame(tick);}show();tick();return{show,fit};}
